from author_helpers import *

# The November 1969 leaf physically precedes the February 1970 leaf.
talk(183,'1969-11-17','Edwin Hewitt','P000293','Sharp Fourier inequalities on compact groups',r'Hewitt discusses Fourier transforms with matrix-valued coefficients, Plancherel and Hausdorff--Young, and the functions giving equality. The preliminary list of names concerning singular values contains no actual inequality. This leaf precedes the 1970 heading and the February Kazhdan lecture in the manuscript, notwithstanding the catalogue record numbers.')
item(183,'P000293','remark','Unspecified singular-value inequalities',r'The heading \ru{О s-числах} is followed by Gantmacher, Wielandt, Berezin--Gelfand, Weyl and Ky Fan, with a reference to Trudy MMO and semisimple groups.',r'Singular values of a compact operator are the eigenvalues of its absolute value, counted with multiplicity. The notebook does not state which inequality, representation-theoretic construction or extension to semisimple groups is intended.',r'The checked Fourier-inequality literature confirms the use of Schatten norms, but does not identify an individual theorem from this list. No result is assigned solely on the basis of the named authors.',cls='F',literal='not determinable',match='none found',verification='unresolved lead',status='As of 9 November 2026: the precise singular-value claim remains unidentified; the names and publication hint are retained as a research lead.',confidence='low')
item(183,'P000293','definition','Weighted Schatten norms for the compact-group Fourier transform',r'The displayed \(p\)-norm is a sum over irreducibles weighted by \(d_\sigma\), but lacks a readable final exponent and a closing argument parenthesis.',r'For a compact group \(G\) with normalized Haar measure, let \(\widehat G\) denote the unitary irreducibles and \(\widehat f(\sigma)=\int_G f(g)\sigma(g)^*\,dg\). For \(1\leq p<\infty\), put \(\|A\|_{\ell^p(\widehat G)}=(\sum_\sigma d_\sigma\operatorname{Tr}|A_\sigma|^p)^{1/p}\); for \(p=\infty\), use \(\sup_\sigma\|A_\sigma\|_{\mathrm{op}}\). The sum is interpreted over the finite-support partial sums if the dual is uncountable.',r'These are the standard compact-group Fourier norms used in \citet[Section 43]{hewittross1970abstract} and in the compact case of \citet[pp.~293--294]{russo1974fourier}. The missing root is a mathematical emendation, not an established reading of the handwriting.',refs=['hewittross1970abstract','russo1974fourier'],literal='false as written',verification='indirect',reconstruction=r'Normalized Haar measure, Schatten rather than entrywise norms, and the exponent \(1/p\) are made explicit.')
item(183,'P000293','theorem','Peter--Weyl--Plancherel identity',r'The notebook states \(\|\widehat f\|_2^2=\int_G|f|^2\,d\lambda\).',r'For a compact group with Haar probability measure and \(f\in L^2(G)\), \(\sum_{\sigma\in\widehat G}d_\sigma\operatorname{Tr}(\widehat f(\sigma)^*\widehat f(\sigma))=\|f\|_2^2\). Equivalently, the Fourier transform extends to a unitary onto the Hilbert direct sum of the matrix spaces with these weights.',r'This is the classical compact-group Plancherel theorem, explicitly named as background in the lecture and in \citet[Section 43]{hewittross1970abstract}; the later publication is not its origin.',refs=['hewittross1970abstract'],literal='correct with missing hypotheses',verification='indirect')
item(183,'P000293','theorem','Compact-group Riemann--Lebesgue lemma',r'For every \(f\in L^1(G)\) and \(\varepsilon>0\), only finitely many irreducibles have Fourier coefficient operator norm larger than \(\varepsilon\).',r'For a compact group and \(f\in L^1(G)\), the field \(\widehat f(\sigma)\) vanishes at infinity in operator norm on the discrete dual: \(\{\sigma:\|\widehat f(\sigma)\|_{\mathrm{op}}>\varepsilon\}\) is finite for every \(\varepsilon>0\). Approximation by finite linear combinations of matrix coefficients proves the assertion, using \(\|\widehat f(\sigma)\|_{\mathrm{op}}\leq\|f\|_1\).',r'This is standard Peter--Weyl Fourier theory, as treated by \citet{hewittross1970abstract}. The elementary approximation argument supplies the exact operator-norm formulation recorded in the notes.',refs=['hewittross1970abstract'],literal='correct',verification='indirect')
item(183,'P000293','theorem','Kunze--Hausdorff--Young inequality',r'The notes attribute \(\|\widehat f\|_{p^{\prime}}\leq\|f\|_p\), \(1<p<2\), to Kunze and label it Hausdorff--Young.',r'Let \(G\) be compact with Haar probability measure and \(1\leq p\leq2\), \(p^{\prime}=p/(p-1)\). Then \(\|\widehat f\|_{\ell^{p^{\prime}}(\widehat G)}\leq\|f\|_{L^p(G)}\), with the \(p=1\) target interpreted in operator norm. The coefficient norm is the weighted Schatten norm, not a scalar norm on matrix entries.',r'Kunze published the unimodular-group extension in 1958, as explicitly documented in \citet[Introduction and reference 8]{russo1974fourier}. Its compact specialization is the theorem in the notes; this also continues the earlier seminar discussion 1967-137.11.',refs=['russo1974fourier','hewittross1970abstract'],literal='correct with missing hypotheses',verification='read the result')
item(183,'P000293','theorem','Equality on the circle',r'The Hardy--Littlewood theorem is stated as equality only for \(f(x)=\alpha e^{inx}\).',r'For \(1<p<2\) and nonzero \(f\in L^p(\mathbb T)\), equality in Hausdorff--Young holds exactly when \(f(x)=c e^{inx}\) almost everywhere, for some nonzero \(c\in\mathbb C\) and \(n\in\mathbb Z\). The zero function is an additional trivial equality case; at the endpoint \(p=2\), all functions give equality.',r'The circle statement is the classical Hardy--Littlewood equality case, discussed as the antecedent of the compact-group result in \citet[pp.~293--294]{russo1974fourier}. It follows as well from the compact-group characterization, because the circle has no proper open subgroup.',refs=['russo1974fourier'],literal='correct with missing hypotheses',verification='read the result')
item(183,'P000293','theorem','Compact-group Hausdorff--Young extremizers',r'The general-group examples are continuous multiplicative functions on an open subgroup \(G_0\), equal to one at the identity and extended by zero outside \(G_0\).',r'For a compact group \(G\), \(1<p<2\), and nonzero \(f\in L^p(G)\), equality holds exactly for functions \(f(x)=c\chi(x_0^{-1}x)\mathbf1_{x_0H}(x)\) almost everywhere, where \(H\) is an open subgroup, \(\chi:H\to U(1)\) is a continuous character, \(x_0\in G\), and \(c\ne0\). Openness makes \(H\) compact; translation and scalar multiplication preserve the equality.',r'The compact-group result appears in \citet[Section 43]{hewittross1970abstract}, published in 1970 after this November 1969 lecture. \citet[Theorem 1 and pp.~293--294]{russo1974fourier} states the broader unimodular theorem and expressly credits Hewitt--Ross for the compact case. The exact theorem was read in Russo; the original book was checked through publisher metadata and this explicit attribution. The notebook provides subgroup representatives and omits translates and scalar multiples from the final line.',refs=['hewittross1970abstract','russo1974fourier'],cls='A',literal='correct with missing hypotheses',match='exact',verification='indirect',status='As of 9 November 2026: the compact-group equality classification is established. The verified chronology is the 17 November 1969 seminar report followed by the 1970 book; no earlier circulation date or absolute priority is inferred from the checked evidence.',reconstruction='The complete classification, including almost-everywhere equality, translates and scalar multiples, is supplied from the published result.')
item(183,'P000293','method','Interpolation behind Fourier norm inequalities',r'The closing sentence says that analogues of the Riesz--Thorin theorems exist.',r'The Fourier map has endpoint bounds \(L^1(G)\to\ell^\infty(\widehat G)\) and \(L^2(G)\to\ell^2(\widehat G)\). Interpolation in the weighted Schatten spaces gives the compact Hausdorff--Young estimate at intermediate exponents. The sentence does not identify any additional interpolation theorem or a different operator.',r'This is the standard interpolation mechanism in the Hausdorff--Young theory discussed by \citet[Introduction]{russo1974fourier} and \citet[Section 43]{hewittross1970abstract}. Only this explicit application is reconstructed; no unspecified stronger analogue is claimed.',refs=['russo1974fourier','hewittross1970abstract'],literal='correct with missing hypotheses',match='partial',verification='indirect',reconstruction='The endpoint spaces and resulting interpolation application are supplied as an interpretation of the brief remark.')
correction('P000293','Fourier p-norm display',r'\(\|\widehat f\|_p=(\sum_\sigma d_\sigma\|\widehat f(\sigma\|_p^p)\)',r'\(\|\widehat f\|_p=(\sum_\sigma d_\sigma\|\widehat f(\sigma)\|_p^p)^{1/p}\)','The scan has no secure final exponent; homogeneity of a norm requires the p-th root. This emends the formula rather than silently changing the transcription.','both','faithful_error')
